$rules$::jsonb) as x(track text,slot integer,tasks jsonb)
on conflict(track,slot) do update set tasks=excluded.tasks;
alter table public.simulator_competition_runs add column if not exists verified_tasks text[] not null default '{}';
create table if not exists public.simulator_competition_review(
 run_id uuid primary key references public.simulator_competition_runs(id) on delete cascade,
 flags text[] not null default '{}', attempts integer not null default 0,
 window_start timestamptz not null default clock_timestamp(), window_attempts integer not null default 0,
 last_evidence_digest text, reviewed_at timestamptz, review_note text
);
alter table public.simulator_competition_review enable row level security;
revoke all on public.simulator_competition_review from public,anon,authenticated;
insert into public.simulator_competition_review(run_id,flags)
select id,array['legacy_unverified'] from public.simulator_competition_runs where
(completed_at is not null or cardinality(validated_tasks)>0) and cardinality(verified_tasks)=0
on conflict(run_id) do nothing;
create or replace function public.simulator_rule_normalize(v text) returns text language sql immutable set search_path='' as $$
 select lower(regexp_replace(trim(v),'\s+',' ','g'));
$$;
revoke all on function public.simulator_rule_normalize(text) from public,anon,authenticated;

create or replace function public.simulator_competition_verify(p_run uuid,p_evidence jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r public.simulator_competition_runs; rules jsonb; item jsonb; rule jsonb; pair record;
 verified text[]; now_at timestamptz:=clock_timestamp(); failure text; submitted integer; attempt_count integer;
begin
 if auth.uid() is null then raise exception 'Sign in first' using errcode='42501'; end if;
 select * into r from public.simulator_competition_runs where id=p_run and user_id=auth.uid() for update;
 if not found then raise exception 'Start this lab first' using errcode='42501'; end if;
 if r.month<>date_trunc('month',now_at at time zone 'America/Toronto')::date then raise exception 'Month closed' using errcode='22023'; end if;
 if not exists(select 1 from public.simulator_leaderboard_profiles where user_id=auth.uid() and opted_in) then raise exception 'Entry withdrawn' using errcode='42501'; end if;
 insert into public.simulator_competition_review(run_id) values(r.id) on conflict do nothing;
 update public.simulator_competition_review set attempts=attempts+1,
 window_attempts=case when window_start<now_at-interval '1 minute' then 1 else window_attempts+1 end,
 window_start=case when window_start<now_at-interval '1 minute' then now_at else window_start end where run_id=r.id
 returning window_attempts into attempt_count;
 select tasks into rules from public.simulator_lab_rules where track=r.track and slot=r.slot;
 verified:=r.verified_tasks;
 if attempt_count>60 then failure:='Too many submissions. Wait one minute and retry.';
 elsif rules is null then failure:='Lab rules unavailable';
 elsif coalesce(jsonb_typeof(p_evidence),'null')<>'array' then failure:='Evidence must be an array';
 elsif octet_length(p_evidence::text)>131072 or jsonb_array_length(p_evidence)>jsonb_array_length(rules) then failure:='Evidence exceeds the lab limits';
 else
  select count(distinct e->>'id') into submitted from jsonb_array_elements(p_evidence) e;
  if submitted<>jsonb_array_length(p_evidence) then failure:='Duplicate or missing task ID'; end if;
  if exists(select 1 from jsonb_array_elements(p_evidence) e where not exists(select 1 from jsonb_array_elements(rules) x where x->>'id'=e->>'id')) then failure:='Unknown task'; end if;
  -- Catalogue order is prerequisite order, regardless of how a retry payload is ordered.
  for rule in select value from jsonb_array_elements(rules) loop
   exit when failure is not null;
   select value into item from jsonb_array_elements(p_evidence) where value->>'id'=rule->>'id';
   if item is null then continue; end if;
   if exists(select 1 from jsonb_array_elements_text(rule->'dependencies') d where not d=any(verified)) then failure:='Complete prerequisite evidence first';exit;end if;
   if rule->>'type'='form' then
    if coalesce(jsonb_typeof(item->'values'),'null')<>'object' then failure:='Missing configuration evidence';exit;end if;
    for pair in select key,value from jsonb_each_text(rule->'expected') loop
     if jsonb_typeof(item->'values'->pair.key) is distinct from 'string' or public.simulator_rule_normalize(item->'values'->>pair.key) is distinct from public.simulator_rule_normalize(pair.value) then failure:='Configuration does not satisfy the lab requirements';exit;end if;
    end loop;
   else
    if coalesce(jsonb_typeof(item->'commands'),'null')<>'array' then failure:='Missing command evidence';exit;end if;
    if exists(select 1 from jsonb_array_elements_text(rule->'required') cmd where not exists(select 1 from jsonb_array_elements_text(item->'commands') actual where public.simulator_rule_normalize(actual)=public.simulator_rule_normalize(cmd))) then failure:='Required verification commands are missing';exit;end if;
   end if;
   if not (rule->>'id')=any(verified) then verified:=array_append(verified,rule->>'id'); end if;
  end loop;
 end if;
 if failure is not null then
  update public.simulator_competition_review set flags=array(select distinct f from unnest(flags||array[case when attempt_count>60 then 'rate_limit' else 'rejected_evidence' end]) f),reviewed_at=null where run_id=r.id;
  return jsonb_build_object('accepted',false,'message',failure);
 end if;
 update public.simulator_competition_review set last_evidence_digest=md5(p_evidence::text) where run_id=r.id;
 if verified is distinct from r.verified_tasks then
  update public.simulator_competition_runs set verified_tasks=verified,
  validated_tasks=array(select distinct t from unnest(validated_tasks||verified) t),last_activity_at=now_at where id=r.id;
 end if;
 if cardinality(verified)=jsonb_array_length(rules) and now_at-r.started_at<jsonb_array_length(rules)*interval '2 seconds' then
  update public.simulator_competition_review set flags=array(select distinct f from unnest(flags||array['rapid_completion']) f),reviewed_at=null where run_id=r.id;
 end if;
 return jsonb_build_object('accepted',true,'validated',cardinality(verified));
end; $$;
revoke all on function public.simulator_competition_verify(uuid,jsonb) from public,anon;
grant execute on function public.simulator_competition_verify(uuid,jsonb) to authenticated;
-- Close the old task-ID-only scoring path. Old clients must refresh and replay to provide evidence.
create or replace function public.simulator_competition_activity(p_run uuid,p_tasks text[])
returns integer language plpgsql security definer set search_path='' as $$
begin raise exception 'Refresh the simulator: configuration and command evidence are required' using errcode='42501'; end; $$;
create or replace function public.simulator_competition_finish(p_run uuid)
returns integer language plpgsql security definer set search_path='' as $$
declare r public.simulator_competition_runs; allowed text[]; now_at timestamptz:=clock_timestamp();
begin
 if auth.uid() is null then raise exception 'Sign in first' using errcode='42501'; end if;
 select * into r from public.simulator_competition_runs where id=p_run and user_id=auth.uid() for update;
 if not found then raise exception 'Start this lab first' using errcode='42501'; end if;
 if r.month<>date_trunc('month',now_at at time zone 'America/Toronto')::date then raise exception 'Month closed' using errcode='22023'; end if;
 if not exists(select 1 from public.simulator_leaderboard_profiles where user_id=auth.uid() and opted_in) then raise exception 'Entry withdrawn' using errcode='42501'; end if;
 if r.completed_at is not null then return 0; end if;
 select task_ids into allowed from public.simulator_lab_task_catalog where track=r.track and slot=r.slot;
 if allowed is null or not allowed<@r.verified_tasks then raise exception 'All tasks need server-verified evidence before completion' using errcode='42501'; end if;
 update public.simulator_competition_runs set completed_at=now_at where id=r.id;
 return ((r.slot-1)/5+1)*100;
end; $$;
commit;
